var sb = new System.Text.StringBuilder();
var cars = UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None);
var car = GameObject.Find("GARAGE / PLAYER");
if (car == null) return "no car";
// The rear wheels are the ground truth for the tail: wheel_rl / wheel_rr sit
// behind wheel_fl / wheel_fr in the car's own local space.
var rl = car.transform.Find("BODY / hdSportsCar/wheel_rl");
var fl = car.transform.Find("BODY / hdSportsCar/wheel_fl");
sb.AppendLine("bodyRoot found rl=" + (rl != null) + " fl=" + (fl != null));
var kit = car.transform.Find("AURORA light kit");
if (kit != null)
{
    foreach (Transform t in kit)
    {
        if (t.name.Contains("LED") || t.name.Contains("DRL"))
            sb.AppendLine(t.name + " worldPos=" + t.position + " localToCar=" + car.transform.InverseTransformPoint(t.position));
    }
    sb.AppendLine("kit localRot=" + kit.localRotation.eulerAngles);
}
var aero = car.transform.Find("AURORA aero kit");
if (aero != null) sb.AppendLine("aero localRot=" + aero.localRotation.eulerAngles + " localPos=" + aero.localPosition);
// Steering wheel marks the cabin; the bonnet sits ahead of it.
foreach (Transform t in car.GetComponentsInChildren<Transform>())
{
    if (t.name.ToLower().Contains("steering") && t.parent != null)
    {
        sb.AppendLine("steering localToCar=" + car.transform.InverseTransformPoint(t.position));
        break;
    }
}
// Find the wheel nodes anywhere in the hierarchy (they may be nested).
foreach (Transform t in car.GetComponentsInChildren<Transform>())
{
    if (t.name == "wheel_rl" || t.name == "wheel_fl")
        sb.AppendLine(t.name + " localToCar=" + car.transform.InverseTransformPoint(t.position));
}
Debug.Log("PROBE3 " + sb.ToString().Replace("\r", "").Replace("\n", " | "));
return sb.ToString();
